# Runtime reconnect design notes
These notes contain historical noise. Only production contracts should drive the fix.
## Authoritative timeout contract
All heartbeat timestamps and timeout values are milliseconds since/within the same monotonic wall-clock domain. Expiry is `nowMillis - lastHeartbeatMillis > timeoutMillis`; no seconds conversion is permitted.
## Authoritative registry contract
Reconnect is atomic at the semantic level: the object returned from reconnect must be the object observable through SessionRegistry.get(id). Expired sessions may be replaced, but the replacement must be registered before reconnect returns.
---
=== src/main/java/com/acme/runtime/HeartbeatPolicy.java ===
package com.acme.runtime;
public final class HeartbeatPolicy {
 private final long timeoutMillis; public HeartbeatPolicy(long timeoutMillis){this.timeoutMillis=timeoutMillis;}
 public boolean expired(Session s,long nowMillis){ return (nowMillis/1000 - s.lastHeartbeatMillis()) > timeoutMillis; }
}
=== src/main/java/com/acme/runtime/ReconnectCoordinator.java ===
package com.acme.runtime;
public final class ReconnectCoordinator {
 private final SessionRegistry registry; private final HeartbeatPolicy heartbeat;
 public ReconnectCoordinator(SessionRegistry registry, HeartbeatPolicy heartbeat){this.registry=registry;this.heartbeat=heartbeat;}
 public Session reconnect(String id,long nowMillis){
   Session s=registry.get(id);
   if(s==null) { s=new Session(id,nowMillis,true); registry.put(s); return s; }
   if(heartbeat.expired(s,nowMillis)) { registry.remove(id); return new Session(id,nowMillis,true); }
   Session connected=s.withConnected(true).withHeartbeat(nowMillis); registry.put(connected); return connected;
 }
}
=== src/main/java/com/acme/runtime/Session.java ===
package com.acme.runtime;
public record Session(String id, long lastHeartbeatMillis, boolean connected) {
 public Session withHeartbeat(long t){return new Session(id,t,connected);}
 public Session withConnected(boolean c){return new Session(id,lastHeartbeatMillis,c);}
}
=== src/main/java/com/acme/runtime/SessionRegistry.java ===
package com.acme.runtime;
import java.util.concurrent.*;
public final class SessionRegistry {
 private final ConcurrentMap<String,Session> sessions=new ConcurrentHashMap<>();
 public void put(Session s){sessions.put(s.id(),s);}
 public Session get(String id){return sessions.get(id);}
 public void remove(String id){sessions.remove(id);}
 public int size(){return sessions.size();}
}
=== src/test/java/com/acme/runtime/ReconnectCoordinatorTest.java ===
package com.acme.runtime;
public final class ReconnectCoordinatorTest {
 public static void main(String[] args){
  SessionRegistry r=new SessionRegistry(); HeartbeatPolicy p=new HeartbeatPolicy(5_000); ReconnectCoordinator c=new ReconnectCoordinator(r,p);
  r.put(new Session("S1",1_000_000L,false));
  Session a=c.reconnect("S1",1_003_000L);
  if(!a.connected()||a.lastHeartbeatMillis()!=1_003_000L||r.size()!=1) throw new AssertionError("normal reconnect failed");
  r.put(new Session("S2",2_000_000L,false));
  if(!p.expired(r.get("S2"),2_006_001L)) throw new AssertionError("heartbeat timeout must be measured in milliseconds");
  Session b=c.reconnect("S2",2_006_001L);
  if(!b.connected()||b.lastHeartbeatMillis()!=2_006_001L) throw new AssertionError("expired reconnect result wrong");
  if(r.get("S2")!=b || r.size()!=2) throw new AssertionError("reconnected session must remain registered");
  System.out.println("PASS ReconnectCoordinatorTest");
 }
}
